/*BUTTON*/
window.addEventListener("DOMContentLoaded", () => {
  const buttons = document.querySelectorAll(".primary-button");

  buttons.forEach(button => {
    let round = null;

    button.addEventListener("mouseenter", event => {
      if (!round) {
        round = document.createElement("span");
        round.classList.add("round");
        button.appendChild(round);
      }

      const x = event.offsetX;
      const y = event.offsetY;

      round.style.left = `${x}px`;
      round.style.top = `${y}px`;

      // Forzar reflow para que la transición de transform funcione
      void round.offsetWidth;

      button.classList.add("animate");
    });

    button.addEventListener("mouseleave", event => {
      if (round) {
        button.classList.remove("animate");
      }
    });
  });
});

